<?php

namespace App\Support;

use App\Models\Role;
use App\Models\Setting;
use App\Models\User;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;

/**
 * First start of a production install: instead of a seeded admin/password,
 * the operator creates the first administrator under /setup.
 *
 * Whoever reaches a fresh instance first could otherwise claim it - so the
 * page needs a one-time setup code. It comes from SETUP_TOKEN in the .env or
 * is generated by the production seeder (or "php artisan setup:code") and
 * printed to the console / container log. Only its hash is stored.
 *
 * Setup is pending only while a code exists and there is no administrator:
 * existing installations and the demo never see the page.
 */
class InitialSetup
{
    public static function pending(): bool
    {
        if (blank(config('custom.setup_token')) && blank(Setting::wert(Setting::SETUP_CODE))) {
            return false;
        }

        return ! self::hasAdmin();
    }

    public static function hasAdmin(): bool
    {
        return User::where('role_id', Role::IS_ADMIN)->exists();
    }

    /** A new code; any earlier generated one stops working. */
    public static function newCode(): string
    {
        $code = implode('-', str_split(Str::upper(Str::random(20)), 5));

        Setting::setzen(Setting::SETUP_CODE, Hash::make($code));

        return $code;
    }

    public static function check(?string $code): bool
    {
        $code = trim((string) $code);

        if ($code === '') {
            return false;
        }

        $fromEnv = (string) config('custom.setup_token');
        if ($fromEnv !== '' && hash_equals($fromEnv, $code)) {
            return true;
        }

        $hash = Setting::wert(Setting::SETUP_CODE);

        // Case-insensitive: the generated code is upper case, typed from a
        // log it often is not.
        return filled($hash) && Hash::check(Str::upper($code), $hash);
    }

    /** The code has done its job - it must not open anything again. */
    public static function finish(): void
    {
        Setting::setzen(Setting::SETUP_CODE, null);
    }
}
